#pragma once#include "BaseReader.h"class KDI : public KBaseReader{public:  KDI();  virtual std::string GetType() const  {    return "DI";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;  std::string szLast;};//////////////////////////////////////////////////////////////////////////class KDIFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KDI();    return ptr;  }};